import numpy as np
e=np.asarray(df['eps']);T=np.asarray(df['T']);s=np.asarray(df['sigma'])
L=np.log(e)
base={'1':np.ones_like(e),'e':e,'L':L,'1/e':1/e,'e2':e**2,'eL':e*L,'1/e2':1/e**2,'sq':np.sqrt(e),'L2':L**2,'L/e':L/e}
def run(keys,Tp=3):
    cols=[];names=[]
    for bn in keys:
        for k in range(Tp+1):
            names.append(f'{bn}*T^{k}'); cols.append(base[bn]*T**k)
    X=np.vstack(cols).T
    c,_,_,_=np.linalg.lstsq(X,s,rcond=None)
    r=s-X@c
    return np.mean(r**2)/np.var(s),names,c
for keys in [['1','e','L','1/e','e2','eL'],['1','e','L','1/e','e2','1/e2'],['1','e','L','1/e','sq','L2'],['1','e','L','1/e','L/e'],['1','e','L','1/e','e2','L2','eL','1/e2']]:
    n,names,c=run(keys)
    print(keys, n)
